-- RenfyGrid -- 0026_questionnaire_cap.sql
-- Track D, D0.6 (2026-10-05): la CAP (conocimientos, actitudes y practicas)
-- como cuestionario. Fuente: Guia 7 de Municipios Azules, T-04 "Encuesta CAP
-- inicial y final" (18 preguntas, 3 por guia, textos literales) y T-05 "Clave
-- y matriz de analisis CAP" (2 puntos a la opcion esperada, 0 a las demas;
-- analisis por guia y por dimension; rangos Alto 80-100, Medio 50-79, Bajo 0-49).
--
-- Cambios GENERICOS al modelo (sirven a cualquier cuestionario de cualquier
-- programa, nada de esto sabe que es la CAP):
--   kind 'questionnaire'.
--   items[].options  -- escala propia del item (opcion multiple). La clave
--                       de respuestas es el `score` de cada opcion: dato del
--                       paquete, nunca codigo.
--   items[].groups   -- a que grupos pertenece el item (guia, dimension).
--   run_fields       -- datos que pide cada aplicacion (momento, participante).
--   analysis         -- como se analiza: comparar por momento, agrupar, rangos.
--   checklist_run.context -- los valores de run_fields de cada aplicacion.
-- Etapa nueva INT de la ruta: la jornada 8 de la Guia 7 (integracion, CAP
-- final, seguimiento 7-30-90). La CAP inicial se aplica el dia 1 con la misma
-- lista; la ruta la muestra en INT porque ahi se analiza la comparacion.

ALTER TABLE checklist_template DROP CONSTRAINT checklist_template_kind_check;
ALTER TABLE checklist_template ADD CONSTRAINT checklist_template_kind_check
    CHECK (kind IN ('inspection', 'traffic_light', 'self_assessment', 'products', 'questionnaire'));
ALTER TABLE checklist_template ADD COLUMN run_fields jsonb NOT NULL DEFAULT '[]';
ALTER TABLE checklist_template ADD COLUMN analysis jsonb;
ALTER TABLE checklist_run ADD COLUMN context jsonb NOT NULL DEFAULT '{}';

INSERT INTO process_stage (pack_id, code, sort_order, title, source_ref, purpose, products) VALUES
('EC-MUNICIPIOS-AZULES', 'INT', 7, 'Integración, evaluación y seguimiento', 'Guía 7 · Jornada 8 y seguimiento 7-30-90',
 'Comparar lo aprendido (CAP inicial y final), revisar la carpeta de productos y verificar después que los productos se usan.',
 '["CAP inicial y final comparada", "Pasaporte de productos revisado", "Acuerdos de seguimiento a 7, 30 y 90 días"]');

INSERT INTO checklist_template (id, pack_id, kind, title, purpose, scale, items, stage_code, run_fields, analysis) VALUES
('MA-CAP', 'EC-MUNICIPIOS-AZULES', 'questionnaire', 'T-04. Encuesta CAP inicial y final',
 'Comparar conocimientos, actitudes y prácticas asociados a las seis guías. Se aplica el Día 1 y el Día 8, con las mismas preguntas y condiciones. Marque una sola opción. La encuesta no es un examen ni se utiliza para sancionar; puede responderse de manera individual o mediante lectura oral.',
 '[]',
 '[{"key": "q01", "text": "Cuando una JAAPS quiere mejorar, el primer paso más útil es:", "groups": {"guide": "G1", "dimension": "knowledge"}, "options": [{"code": "a", "label": "a) Esperar un proyecto externo.", "score": 0}, {"code": "b", "label": "b) Realizar un diagnóstico participativo con evidencia.", "score": 2}, {"code": "c", "label": "c) Cambiar toda la directiva.", "score": 0}]}, {"key": "q02", "text": "Cuando la experiencia comunitaria y un dato técnico parecen diferentes, conviene:", "groups": {"guide": "G1", "dimension": "attitude"}, "options": [{"code": "a", "label": "a) Ignorar la experiencia.", "score": 0}, {"code": "b", "label": "b) Comparar evidencias y dialogar.", "score": 2}, {"code": "c", "label": "c) Ignorar el dato técnico.", "score": 0}]}, {"key": "q03", "text": "Antes de decidir una mejora, la JAAPS debería:", "groups": {"guide": "G1", "dimension": "practice"}, "options": [{"code": "a", "label": "a) Registrar problema, causa, evidencia y personas afectadas.", "score": 2}, {"code": "b", "label": "b) Actuar sin registrar.", "score": 0}, {"code": "c", "label": "c) Elegir la opción más costosa.", "score": 0}]}, {"key": "q04", "text": "La máxima autoridad de la JAAPS es:", "groups": {"guide": "G2", "dimension": "knowledge"}, "options": [{"code": "a", "label": "a) La presidencia.", "score": 0}, {"code": "b", "label": "b) La asamblea general.", "score": 2}, {"code": "c", "label": "c) El operador.", "score": 0}]}, {"key": "q05", "text": "La rendición de cuentas:", "groups": {"guide": "G2", "dimension": "attitude"}, "options": [{"code": "a", "label": "a) Debilita a la directiva.", "score": 0}, {"code": "b", "label": "b) Protege la organización y fortalece confianza.", "score": 2}, {"code": "c", "label": "c) Solo se hace cuando existe una denuncia.", "score": 0}]}, {"key": "q06", "text": "Después de elegir una directiva, corresponde:", "groups": {"guide": "G2", "dimension": "practice"}, "options": [{"code": "a", "label": "a) Registrar el proceso, archivar el acta y cumplir el trámite aplicable.", "score": 2}, {"code": "b", "label": "b) Esperar hasta el final del período.", "score": 0}, {"code": "c", "label": "c) Guardar el acta únicamente en una casa.", "score": 0}]}, {"key": "q07", "text": "La cloración del agua:", "groups": {"guide": "G3", "dimension": "knowledge"}, "options": [{"code": "a", "label": "a) Es siempre el primer proceso.", "score": 0}, {"code": "b", "label": "b) Es la etapa final y puede requerir procesos previos.", "score": 2}, {"code": "c", "label": "c) Reemplaza la filtración en todos los casos.", "score": 0}]}, {"key": "q08", "text": "El EPP y los procedimientos de seguridad:", "groups": {"guide": "G3", "dimension": "attitude"}, "options": [{"code": "a", "label": "a) Son opcionales si el operador tiene experiencia.", "score": 0}, {"code": "b", "label": "b) Son parte del trabajo y deben planificarse.", "score": 2}, {"code": "c", "label": "c) Solo se usan durante visitas.", "score": 0}]}, {"key": "q09", "text": "La operación diaria debería registrarse en:", "groups": {"guide": "G3", "dimension": "practice"}, "options": [{"code": "a", "label": "a) Memoria del operador.", "score": 0}, {"code": "b", "label": "b) Bitácora y registros de control.", "score": 2}, {"code": "c", "label": "c) Mensajes informales.", "score": 0}]}, {"key": "q10", "text": "Una tarifa sustentada se calcula con:", "groups": {"guide": "G4", "dimension": "knowledge"}, "options": [{"code": "a", "label": "a) Costos reales y recaudación esperada.", "score": 2}, {"code": "b", "label": "b) El valor de una comunidad vecina.", "score": 0}, {"code": "c", "label": "c) Una cifra escogida por una persona.", "score": 0}]}, {"key": "q11", "text": "Hablar abiertamente de costos y tarifa:", "groups": {"guide": "G4", "dimension": "attitude"}, "options": [{"code": "a", "label": "a) Es necesario para decidir y rendir cuentas.", "score": 2}, {"code": "b", "label": "b) Debe evitarse siempre.", "score": 0}, {"code": "c", "label": "c) Solo corresponde a tesorería.", "score": 0}]}, {"key": "q12", "text": "Cada ingreso y egreso debe:", "groups": {"guide": "G4", "dimension": "practice"}, "options": [{"code": "a", "label": "a) Tener registro, soporte y saldo actualizado.", "score": 2}, {"code": "b", "label": "b) Registrarse solo si es grande.", "score": 0}, {"code": "c", "label": "c) Recordarse al final del año.", "score": 0}]}, {"key": "q13", "text": "El cuidado del agua potable depende:", "groups": {"guide": "G5", "dimension": "knowledge"}, "options": [{"code": "a", "label": "a) Solo de la captación.", "score": 0}, {"code": "b", "label": "b) De la fuente, sistema, saneamiento, higiene y hogar.", "score": 2}, {"code": "c", "label": "c) Solo del cloro.", "score": 0}]}, {"key": "q14", "text": "Proteger la microcuenca es responsabilidad:", "groups": {"guide": "G5", "dimension": "attitude"}, "options": [{"code": "a", "label": "a) Únicamente de la JAAPS.", "score": 0}, {"code": "b", "label": "b) Compartida entre actores del territorio.", "score": 2}, {"code": "c", "label": "c) Solo de propietarios privados.", "score": 0}]}, {"key": "q15", "text": "Después de lluvias fuertes, cortes o reparaciones, conviene:", "groups": {"guide": "G5", "dimension": "practice"}, "options": [{"code": "a", "label": "a) Verificar calidad y asegurar almacenamiento adecuado.", "score": 2}, {"code": "b", "label": "b) Consumir sin revisar.", "score": 0}, {"code": "c", "label": "c) Añadir cualquier cloro disponible.", "score": 0}]}, {"key": "q16", "text": "Un Plan de Mejora completo incluye:", "groups": {"guide": "G6", "dimension": "knowledge"}, "options": [{"code": "a", "label": "a) Solo una lista de problemas.", "score": 0}, {"code": "b", "label": "b) Línea base, metas, actividades, recursos, indicadores y seguimiento.", "score": 2}, {"code": "c", "label": "c) Solo un presupuesto.", "score": 0}]}, {"key": "q17", "text": "Al priorizar problemas conviene revisar:", "groups": {"guide": "G6", "dimension": "attitude"}, "options": [{"code": "a", "label": "a) Solo facilidad.", "score": 0}, {"code": "b", "label": "b) Criticidad y factibilidad.", "score": 2}, {"code": "c", "label": "c) Solo costo.", "score": 0}]}, {"key": "q18", "text": "El Plan de Mejora debe:", "groups": {"guide": "G6", "dimension": "practice"}, "options": [{"code": "a", "label": "a) Aprobarse, ejecutarse y revisarse con evidencias.", "score": 2}, {"code": "b", "label": "b) Guardarse sin seguimiento.", "score": 0}, {"code": "c", "label": "c) depender de una sola persona.", "score": 0}]}]',
 'INT',
 '[{"key": "moment", "label": "Momento", "required": true, "options": [{"code": "initial", "label": "Inicial"}, {"code": "final", "label": "Final"}]}, {"key": "participant_code", "label": "Código de participante", "required": true, "help": "Use el mismo código en las dos aplicaciones."}]',
 '{"source": "Guía 7, T-05 · Clave y matriz de análisis CAP", "compare_by": "moment", "participant_field": "participant_code", "compare": [{"code": "initial", "label": "Inicial"}, {"code": "final", "label": "Final"}], "group_by": [{"key": "guide", "label": "Guía", "values": {"G1": "Guía 1", "G2": "Guía 2", "G3": "Guía 3", "G4": "Guía 4", "G5": "Guía 5", "G6": "Guía 6"}}, {"key": "dimension", "label": "Dimensión", "values": {"knowledge": "Conocimientos", "attitude": "Actitudes", "practice": "Prácticas"}}], "levels": [{"min_pct": 80, "label": "Alto"}, {"min_pct": 50, "label": "Medio"}, {"min_pct": 0, "label": "Bajo"}], "note": "Utilice estos rangos como orientación y complemente con productos, observaciones y seguimiento. Si una guía muestra bajo avance en sus tres ítems, revise claridad del lenguaje, pertinencia del ejemplo, tiempo, dinámica, formato y dificultad técnica. No atribuya automáticamente el resultado al grupo."}');
